  window.STUDY_DATA.questions.push({"id":"n44","module":"major","subject":"计算机网络基础","chapter":"ch-net-3","knowledgePoint":"IP与子网","type":"single","stem":"子网掩码 255.255.0.0 是（　）","options":["/8","/16","/24","/32"],"answer":"/16","pitfalls":["网络地址不是最小主机，广播地址不是最大主机","可用主机数要减2"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-net","difficultyLabel":"基础","tags":["IP与子网","ch-net-3"],"explainLevel":"subject-specific","hint":"【结论】/16 【考点】IP与子网 【一步步怎么算】 ① 题目：子网掩码 255.255.0.0 是（ ）。 ② 调用「IP与子网」规则（掩码/端口/层次）。 ③ 按步骤计算或对照表格。 ④ 得到 /16。 【其他选项为何不对】 • A「/","analysis":"【审题】题干问「子网掩码255.255.0.0是（　）」，考掩码与CIDR换算。255.255.0.0=/16。\n【协议/层次】网络层·子网掩码。掩码255.255.0.0=11111111.11111111.00000000.00000000，前16位是1→/16。\n【步骤/计算过程】\n① 掩码转二进制：255.255.0.0=11111111.11111111.00000000.00000000。\n② 数1的个数：8+8=16。\n③ CIDR=/16。\n④ 选项：A「/8」❌；B「/16」✅；C「/24」❌；D「/32」❌。\n【答案】B /16\n【易错】①数错：255=8个1，两个255=16个1→/16；②对照：255.255.0.0=/16（B类默认掩码）；③口诀：「255.255.0.0=/16」。","steps":["【IP地址=门牌号，子网掩码=划分街道的规则】","【第一步】把IP和子网掩码都转成二进制","【第二步】按位与（AND）= 网络地址","【第三步】主机位全置1 = 广播地址","【可用主机数】= 2^主机位 - 2（减去网络地址和广播地址）","【答案】/16","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"]});
  window.STUDY_DATA.questions.push({"id":"n47","module":"major","subject":"计算机网络基础","chapter":"ch-net-3","knowledgePoint":"IP与子网","type":"single","stem":"主机位 8 位，可用主机数（　）","options":["256","254","255","250"],"answer":"254","pitfalls":["网络地址不是最小主机，广播地址不是最大主机","可用主机数要减2"],"difficulty":1,"source":"highfreq","typeLabel":"单选","video":"v-net","difficultyLabel":"基础","tags":["IP与子网","ch-net-3"],"explainLevel":"subject-specific","hint":"【结论】254 【考点】IP与子网 【一步步怎么算】 ① 题目：主机位 8 位，可用主机数（ ）。 ② 调用「IP与子网」规则（掩码/端口/层次）。 ③ 按步骤计算或对照表格。 ④ 得到 254。 【其他选项为何不对】 • A「256」：层","analysis":"【审题】题干问「主机位8位，可用主机数」，子网计算题，逐步算。可用主机数=2^主机位-2。\n【协议/层次】网络层·子网计算。可用主机数=2^h-2（h为主机位位数），减2是减去网络地址（主机位全0）和广播地址（主机位全1）。\n【步骤/计算过程】\n① 主机位h=8位。\n② 总地址数=2^8=256个（主机位从00000000到11111111）。\n③ 减去网络地址（主机位全0）1个。\n④ 减去广播地址（主机位全1）1个。\n⑤ 可用主机数=256-2=254。\n⑥ 选项：A「256」=总数❌；B「254」=可用✅；C「255」❌；D「250」❌。\n【答案】B 254\n【易错】①选A256：256是总地址数，可用要减2；②选C255：只减了1个；③公式：可用主机数=2^h-2；④主机位8位→256-2=254，主机位6位→64-2=62。","steps":["【IP地址=门牌号，子网掩码=划分街道的规则】","【第一步】把IP和子网掩码都转成二进制","【第二步】按位与（AND）= 网络地址","【第三步】主机位全置1 = 广播地址","【可用主机数】= 2^主机位 - 2（减去网络地址和广播地址）","【答案】254","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"]});
