  window.STUDY_DATA.questions.push({"id":"nn4604","module":"major","subject":"计算机网络基础","chapter":"ch-net-4","knowledgePoint":"CIDR","type":"single","typeLabel":"单选","stem":"CIDR表示法192.168.1.0/24中24表示（　）","options":["网络位长度","主机位长度","子网数","主机数"],"answer":"网络位长度","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["网络层","CIDR"],"analysis":"【审题】题干问「CIDR表示法192.168.1.0/24中24表示」，考CIDR含义。/24=网络位长度。\n【协议/层次】网络层·CIDR。CIDR「/N」中N=网络位（前缀）长度，即掩码中1的个数。192.168.1.0/24表示前24位是网络位，后8位是主机位。\n【步骤/计算过程】\n① /24中的24=网络位长度（前缀长度）。\n② 选项：A「网络位长度」✅；B「主机位长度」❌（主机位=32-24=8）；C「子网数」❌；D「主机数」❌。\n【答案】A 网络位长度\n【易错】①选B：主机位长度=32-24=8，不是24；②CIDR /N的N是网络位长度；③口诀：「CIDR /N，N是网络位」。","steps":["【考点】CIDR","【协议/层次】网络层·CIDR。CIDR「/N」中N=网络位（前缀）长度，即掩码中1的个数。192.168.1.0/24表示前24位是网络位，后8位是主机位。","【步骤/计算过程】\n① /24中的24=网络位长度（前缀长度）。\n② 选项：A「网络位长度」✅；B「主机位长度」❌（主机位=32-24=8）；C「子网数」❌；D「主机数」❌。","【答案】网络位长度","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn4607","module":"major","subject":"计算机网络基础","chapter":"ch-net-4","knowledgePoint":"IP地址主机位全1","type":"single","typeLabel":"单选","stem":"主机位全1的IP地址是（　）","options":["广播地址","网络地址","环回地址","组播地址"],"answer":"广播地址","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["网络层","广播地址"],"analysis":"【审题】题干问「主机位全1的IP地址是」，考特殊地址定义。主机位全1=广播地址。\n【协议/层次】网络层·特殊地址。主机位全0=网络地址（标识网段）；主机位全1=广播地址（向网段内所有主机广播）。\n【步骤/计算过程】\n① 主机位全1→广播地址。\n② 选项：A「广播地址」✅；B「网络地址」=主机位全0❌；C「环回地址」=127.x❌；D「组播地址」=224.x❌。\n【答案】A 广播地址\n【易错】①选B：网络地址是主机位全0；②「主机位全0=网络地址，主机位全1=广播地址」；③口诀：「全0网络，全1广播」。","steps":["【IP地址=门牌号，子网掩码=划分街道的规则】","【第一步】把IP和子网掩码都转成二进制","【第二步】按位与（AND）= 网络地址","【第三步】主机位全置1 = 广播地址","【可用主机数】= 2^主机位 - 2（减去网络地址和广播地址）","【答案】广播地址","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["网络地址不是最小主机，广播地址不是最大主机","可用主机数要减2"]});
  window.STUDY_DATA.questions.push({"id":"nn4608","module":"major","subject":"计算机网络基础","chapter":"ch-net-4","knowledgePoint":"子网掩码作用","type":"single","typeLabel":"单选","stem":"子网掩码作用是（　）","options":["区分网络位和主机位","分配IP","加密","压缩"],"answer":"区分网络位和主机位","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["网络层","子网掩码"],"analysis":"【审题】题干问「子网掩码作用是」，考掩码功能。掩码作用=区分网络位和主机位。\n【协议/层次】网络层·子网掩码。子网掩码作用：与IP地址按位与运算，区分网络位与主机位，计算网络地址。\n【步骤/计算过程】\n① 掩码作用=区分网络位/主机位。\n② 选项：A「区分网络位和主机位」✅；B「分配IP」=DHCP❌；C「加密」❌；D「压缩」❌。\n【答案】A 区分网络位和主机位\n【易错】①选B：IP分配是DHCP；②掩码1对应网络位，0对应主机位；③口诀：「掩码1网络0主机」。","steps":["【IP地址=门牌号，子网掩码=划分街道的规则】","【第一步】把IP和子网掩码都转成二进制","【第二步】按位与（AND）= 网络地址","【第三步】主机位全置1 = 广播地址","【可用主机数】= 2^主机位 - 2（减去网络地址和广播地址）","【答案】区分网络位和主机位","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["网络地址不是最小主机，广播地址不是最大主机","可用主机数要减2"]});
  window.STUDY_DATA.questions.push({"id":"nn4609","module":"major","subject":"计算机网络基础","chapter":"ch-net-4","knowledgePoint":"路由器功能","type":"single","typeLabel":"单选","stem":"路由器主要功能是（　）","options":["路由选择和分组转发","放大信号","MAC地址学习","加密数据"],"answer":"路由选择和分组转发","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["网络层","路由器"],"analysis":"【审题】题干问「路由器主要功能是」，考路由器功能。路由器功能=路由选择和分组转发。\n【协议/层次】网络层·路由器。路由器两大功能：①路由选择（Routing）：维护路由表，选最优路径；②分组转发（Forwarding）：把分组从入接口转到出接口。\n【步骤/计算过程】\n① 路由器功能=路由选择+分组转发。\n② 选项：A「路由选择和分组转发」✅；B「放大信号」=中继器❌；C「MAC地址学习」=交换机❌；D「加密数据」=安全设备❌。\n【答案】A 路由选择和分组转发\n【易错】①选B：放大信号是中继器；②选C：MAC学习是交换机；③口诀：「路由器选路转发」。","steps":["【考点】路由器功能","【协议/层次】网络层·路由器。路由器两大功能：①路由选择（Routing）：维护路由表，选最优路径；②分组转发（Forwarding）：把分组从入接口转到出接口。","【步骤/计算过程】\n① 路由器功能=路由选择+分组转发。\n② 选项：A「路由选择和分组转发」✅；B「放大信号」=中继器❌；C「MAC地址学习」=交换机❌；D「加密数据」=安全设备❌。","【答案】路由选择和分组转发","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn4611","module":"major","subject":"计算机网络基础","chapter":"ch-net-4","knowledgePoint":"私有地址","type":"single","typeLabel":"单选","stem":"以下哪个是私有地址？（　）","options":["10.0.0.1","8.8.8.8","202.103.0.1","114.114.114.114"],"answer":"10.0.0.1","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["网络层","私有地址"],"analysis":"【审题】题干问「以下哪个是私有地址」，考私有地址识别。10.0.0.1是A类私有地址。\n【协议/层次】网络层·私有地址（RFC1918）：A类10.0.0.0/8、B类172.16.0.0/12、C类192.168.0.0/16。8.8.8.8（Google DNS）、202.103.0.1、114.114.114.114（国内DNS）都是公网地址。\n【步骤/计算过程】\n① 逐个判断：10.0.0.1在10.0.0.0/8私有范围✅；8.8.8.8=公网DNS❌；202.103.0.1=公网❌；114.114.114.114=公网DNS❌。\n② 所以只有选项A（10.0.0.1）是私有地址，其余均为公网地址。\n【答案】A 10.0.0.1\n【易错】①选B/D：8.8.8.8和114.114.114.114是公共DNS服务器（公网IP）；②私有地址三段：10.x、172.16-31.x、192.168.x；③口诀：「10、172.16-31、192.168是私有」。","steps":["【考点】私有地址","【协议/层次】网络层·私有地址（RFC1918）：A类10.0.0.0/8、B类172.16.0.0/12、C类192.168.0.0/16。8.8.8.8（Google DNS）、202.103.0.1、114.114.114.114（国内DNS）都是公网地址。","【步骤/计算过程】\n① 逐个判断：10.0.0.1在10.0.0.0/8私有范围✅；8.8.8.8=公网DNS❌；202.103.0.1=公网❌；114.114.114.114=公网DNS❌。\n② 选项A。","【答案】10.0.0.1","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nr6","module":"major","subject":"计算机网络基础","chapter":"ch-net-4","knowledgePoint":"传输层","type":"single","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"TCP 三次握手是（　）次","options":["2","3","4","5"],"answer":"3","tags":["TCP"],"source":"batch","pitfalls":["分层思想是网络的核心"],"explainLevel":"subject-specific","hint":"【结论】3 【考点】传输层 【一步步怎么算】 ① 题目：TCP 三次握手是（ ）次。 ② 调用「传输层」规则（掩码/端口/层次）。 ③ 按步骤计算或对照表格。 ④ 得到 3。 【其他选项为何不对】 • A「2」：层次/端口/掩码规则用错。 ","analysis":"【审题】题干问「TCP三次握手是（　）次」，考TCP连接建立。三次握手=3次。\n【协议/层次】传输层·TCP三次握手。①客户端→SYN；②服务器→SYN+ACK；③客户端→ACK。共3次报文交互。\n【步骤/计算过程】\n① TCP建立连接=三次握手。\n② 选项：A「2」❌；B「3」✅；C「4」❌（那是释放）；D「5」❌。\n【答案】B 3\n【易错】①选C4：4是释放连接（四次挥手）；②握手3次，挥手4次；③口诀「握手3」。","steps":["【考点】传输层","【协议/层次】传输层·TCP三次握手。①客户端→SYN；②服务器→SYN+ACK；③客户端→ACK。共3次报文交互。","【步骤/计算过程】\n① TCP建立连接=三次握手。\n② 选项：A「2」❌；B「3」✅；C「4」❌（那是释放）；D「5」❌。","【答案】3","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"]});
  window.STUDY_DATA.questions.push({"id":"nx14","module":"major","subject":"计算机网络基础","chapter":"ch-net-4","knowledgePoint":"传输层","type":"single","typeLabel":"单选","difficulty":1,"difficultyLabel":"基础","stem":"UDP 是（　）","options":["面向连接","无连接","可靠","应用层"],"answer":"无连接","tags":["UDP"],"source":"batch","pitfalls":["分层思想是网络的核心"],"explainLevel":"subject-specific","hint":"【结论】无连接 【考点】传输层 【一步步怎么算】 ① 题目：UDP 是（ ）。 ② 调用「传输层」规则（掩码/端口/层次）。 ③ 按步骤计算或对照表格。 ④ 得到 无连接。 【其他选项为何不对】 • A「面向连接」：层次/端口/掩码规则用错","analysis":"【审题】题干问「UDP是（　）」，考UDP特性。UDP=无连接。\n【协议/层次】传输层·UDP。UDP=无连接、不可靠、面向报文。\n【步骤/计算过程】\n① UDP=无连接。\n② 选项：A「面向连接」=TCP❌；B「无连接」✅；C「可靠」=TCP❌；D「应用层」❌（UDP是传输层）。\n【答案】B 无连接\n【易错】①选A：TCP才是面向连接；②UDP无连接不可靠；③口诀「UDP无连接」。","steps":["【考点】传输层","【协议/层次】传输层·UDP。UDP=无连接、不可靠、面向报文。","【步骤/计算过程】\n① UDP=无连接。\n② 选项：A「面向连接」=TCP❌；B「无连接」✅；C「可靠」=TCP❌；D「应用层」❌（UDP是传输层）。","【答案】无连接","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"]});
  window.STUDY_DATA.questions.push({"id":"exam-net-2026-03","module":"major","subject":"计算机网络基础","chapter":"ch-net-5","knowledgePoint":"TCP/UDP","type":"single","typeLabel":"单选","stem":"以下哪个是面向连接的协议？（　）","options":["TCP","UDP","IP","HTTP"],"answer":"TCP","difficulty":1,"difficultyLabel":"基础","source":"school","tags":["真题","2026"],"analysis":"【审题】题干问「以下哪个是面向连接的协议」，考协议特征辨析。TCP是面向连接。\n【协议/层次】传输层/应用层协议特征。TCP=面向连接；UDP=无连接；IP=无连接（网络层）；HTTP=基于TCP（应用层），但「面向连接」的标准\n【步骤/计算过程】\n① 逐个判断：TCP=面向连接✅；UDP=无连接；IP=无连接；HTTP=应用层（基于TCP）。\n② 所以选项A（TCP）是面向连接的协议，其余均不符合。\n【答案】A TCP\n【易错】①选D HTTP：HTTP基于TCP，但协议本身描述「面向连接」的标准②面向连接=TCP，无连接=UDP/IP；③口诀：「TCP面向连接」。","steps":["【TCP】面向连接、可靠传输、三次握手、四次挥手","【UDP】无连接、不可靠、快、开销小","【什么时候用TCP】文件下载、网页、邮件（要求可靠）","【什么时候用UDP】视频直播、语音、DNS（要求快）","【答案】TCP","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["TCP可靠但慢，UDP快但不可靠"]});
