  window.STUDY_DATA.questions.push({"id":"nn6301","module":"major","subject":"计算机网络基础","chapter":"ch-net-6","knowledgePoint":"应用层功能","type":"single","typeLabel":"单选","stem":"应用层协议是为了解决（　）","options":["某类特定应用问题","路由选择","差错控制","物理连接"],"answer":"某类特定应用问题","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["应用层","功能"],"analysis":"【审题】题干问「应用层协议是为了解决」，考应用层定位。应用层解决某类特定应用问题。\n【协议/层次】TCP/IP应用层。应用层协议面向具体应用需求：HTTP解决网页传输、FTP解决文件传输、SMTP解决邮件发送、DNS解决域名解析。每类应用问题对应特定协议。\n【步骤/计算过程】\n① 应用层定位=解决某类特定应用问题。\n② 选项：A「某类特定应用问题」✅；B「路由选择」=网络层❌；C「差错控制」=链路层/传输层❌；D「物理连接」=物理层❌。\n【答案】A 某类特定应用问题\n【易错】①选B/C/D：路由=网络层，差错控制=链路/传输层，物理连接=物理层；②应用层协议面向应用：HTTP/FTP/SMTP/DNS各解决一类应用问题；③口诀：「应用层解决应用问题」。","steps":["【常用端口要背】","80 = HTTP（网页），443 = HTTPS","21 = FTP，22 = SSH，23 = Telnet","53 = DNS，25 = SMTP（发邮件），110 = POP3（收邮件）","67/68 = DHCP（自动分配IP）","【答案】某类特定应用问题","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["DNS用53，DHCP用67/68，别记混"]});
  window.STUDY_DATA.questions.push({"id":"nn6302","module":"major","subject":"计算机网络基础","chapter":"ch-net-6","knowledgePoint":"HTTP","type":"single","typeLabel":"单选","stem":"HTTP协议默认端口是（　）","options":["80","443","21","25"],"answer":"80","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["应用层","端口"],"analysis":"【审题】题干问「HTTP协议默认端口是」，同n24/mqn1考点。HTTP=80。\n【协议/层次】应用层·HTTP。HTTP默认端口80。\n【步骤/计算过程】\n① HTTP端口=80。\n② 选项：A「80」✅；B「443」=HTTPS❌；C「21」=FTP❌；D「25」=SMTP❌。\n【答案】A 80\n【易错】同前：HTTP 80。","steps":["【考点】HTTP","【协议/层次】应用层·HTTP。HTTP默认端口80。","【步骤/计算过程】\n① HTTP端口=80。\n② 选项：A「80」✅；B「443」=HTTPS❌；C「21」=FTP❌；D「25」=SMTP❌。","【答案】80","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn6303","module":"major","subject":"计算机网络基础","chapter":"ch-net-6","knowledgePoint":"DNS","type":"single","typeLabel":"单选","stem":"DNS的作用是（　）","options":["域名解析为IP","IP解析为MAC","分配IP","发送邮件"],"answer":"域名解析为IP","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["应用层","DNS"],"analysis":"【审题】题干问「DNS的作用是」，同n26/nn176考点。DNS=域名解析为IP。\n【协议/层次】应用层·DNS。DNS作用：域名→IP。\n【步骤/计算过程】\n① DNS作用=域名解析为IP。\n② 选项：A「域名解析为IP」✅；B「IP解析为MAC」=ARP❌；C「分配IP」=DHCP❌；D「发送邮件」=SMTP❌。\n【答案】A 域名解析为IP\n【易错】同前：DNS域名→IP。","steps":["【考点】DNS","【协议/层次】应用层·DNS。DNS作用：域名→IP。","【步骤/计算过程】\n① DNS作用=域名解析为IP。\n② 选项：A「域名解析为IP」✅；B「IP解析为MAC」=ARP❌；C「分配IP」=DHCP❌；D「发送邮件」=SMTP❌。","【答案】域名解析为IP","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn6304","module":"major","subject":"计算机网络基础","chapter":"ch-net-6","knowledgePoint":"WWW","type":"single","typeLabel":"单选","stem":"WWW是指（　）","options":["万维网","局域网","广域网","城域网"],"answer":"万维网","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["应用层","WWW"],"analysis":"【审题】题干问「WWW是指」，考基本术语。WWW=万维网。\n【协议/层次】应用层·WWW。WWW（World Wide Web，万维网）：基于HTTP的超文本信息系统，不是网络类型。\n【步骤/计算过程】\n① WWW=World Wide Web=万维网。\n② 选项：A「万维网」✅；B「局域网」=LAN❌；C「广域网」=WAN❌；D「城域网」=MAN❌。\n【答案】A 万维网\n【易错】①选B/C/D：WWW是应用（万维网），不是网络覆盖范围分类；②WWW用HTTP/HTTPS，是Internet上的应用；③口诀：「WWW=万维网」。","steps":["【考点】WWW","【协议/层次】应用层·WWW。WWW（World Wide Web，万维网）：基于HTTP的超文本信息系统，不是网络类型。","【步骤/计算过程】\n① WWW=World Wide Web=万维网。\n② 选项：A「万维网」✅；B「局域网」=LAN❌；C「广域网」=WAN❌；D「城域网」=MAN❌。","【答案】万维网","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn6401","module":"major","subject":"计算机网络基础","chapter":"ch-net-6","knowledgePoint":"URL","type":"single","typeLabel":"单选","stem":"URL是指（　）","options":["统一资源定位符","互联网协议","传输协议","邮件协议"],"answer":"统一资源定位符","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["应用层","URL"],"analysis":"【审题】题干问「URL是指」，考基本术语。URL=统一资源定位符。\n【协议/层次】应用层·URL。URL（Uniform Resource Locator，统一资源定位符）：标识Internet上资源的地址，格式：协议://主机名/路径（如http://www.baidu.com/index.html）。\n【步骤/计算过程】\n① URL=Uniform Resource Locator=统一资源定位符。\n② 选项：A「统一资源定位符」✅；B「互联网协议」=IP❌；C「传输协议」=TCP❌；D「邮件协议」=SMTP❌。\n【答案】A 统一资源定位符\n【易错】①选B：IP是互联网协议（网际协议）；②URL是资源地址（网页地址），如http://...；③口诀：「URL=统一资源定位符=网址」。","steps":["【考点】URL","【协议/层次】应用层·URL。URL（Uniform Resource Locator，统一资源定位符）：标识Internet上资源的地址，格式：协议://主机名/路径（如http://www.baidu.com/index.html）。","【步骤/计算过程】\n① URL=Uniform Resource Locator=统一资源定位符。\n② 选项：A「统一资源定位符」✅；B「互联网协议」=IP❌；C「传输协议」=TCP❌；D「邮件协议」=SMTP❌。","【答案】统一资源定位符","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn6501","module":"major","subject":"计算机网络基础","chapter":"ch-net-6","knowledgePoint":"WWW网页","type":"single","typeLabel":"单选","stem":"网页文件默认名是（　）","options":["index.html","home.html","main.html","www.html"],"answer":"index.html","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["应用层","WWW"],"analysis":"【审题】题干问「网页文件默认名是」，考Web服务器默认文档。默认主页=index.html。\n【协议/层次】应用层·Web服务器。Web服务器（如Apache、Nginx）默认文档：index.html（或index.htm、default.html、index.php）。访问目录时自动返回默认文档。\n【步骤/计算过程】\n① 网页默认文件名=index.html。\n② 选项：A「index.html」✅；B「home.html」❌；C「main.html」❌；D「www.html」❌。\n【答案】A index.html\n【易错】①选B/C/D：常见默认文档是index.html；②index.html是最常见的默认主页文件名；③口诀：「默认主页index.html」。","steps":["【考点】WWW网页","【协议/层次】应用层·Web服务器。Web服务器（如Apache、Nginx）默认文档：index.html（或index.htm、default.html、index.php）。访问目录时自动返回默认文档。","【步骤/计算过程】\n① 网页默认文件名=index.html。\n② 选项：A「index.html」✅；B「home.html」❌；C「main.html」❌；D「www.html」❌。","【答案】index.html","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn6602","module":"major","subject":"计算机网络基础","chapter":"ch-net-6","knowledgePoint":"HTTP状态码","type":"single","typeLabel":"单选","stem":"HTTP状态码404表示（　）","options":["请求成功","资源未找到","服务器错误","重定向"],"answer":"资源未找到","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["应用层","HTTP"],"analysis":"【审题】题干问「HTTP状态码404表示」，考HTTP状态码。404=资源未找到。\n【协议/层次】应用层·HTTP状态码。HTTP状态码分类：2xx成功（200 OK）、3xx重定向（301/302）、4xx客户端错误（404 Not Found资源未找到、403 Forbidden禁止）、5xx服务器错误（500 Internal Server Error）。\n【步骤/计算过程】\n① 404=Not Found=资源未找到。\n② 选项：A「请求成功」=200❌；B「资源未找到」=404✅；C「服务器错误」=500❌；D「重定向」=301/302❌。\n【答案】B 资源未找到\n【易错】①选A：200是成功；②选C：500是服务器错误；③4xx是客户端错误，5xx是服务器错误；④口诀：「200成功，301重定向，404找不到，500服务器错」。","steps":["【考点】HTTP状态码","【协议/层次】应用层·HTTP状态码。HTTP状态码分类：2xx成功（200 OK）、3xx重定向（301/302）、4xx客户端错误（404 Not Found资源未找到、403 Forbidden禁止）、5xx服务器错误（500 Internal Server Error）。","【步骤/计算过程】\n① 404=Not Found=资源未找到。\n② 选项：A「请求成功」=200❌；B「资源未找到」=404✅；C「服务器错误」=500❌；D「重定向」=301/302❌。","【答案】资源未找到","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"exam25-net-j01","module":"major","subject":"计算机网络基础","chapter":"ch-net-1","knowledgePoint":"网络分类","type":"judge","typeLabel":"判断","stem":"局域网覆盖范围比广域网大。","options":["正确","错误"],"answer":"错误","difficulty":1,"difficultyLabel":"基础","source":"school","tags":["2025真题","计网"],"analysis":"【审题】题干说「局域网覆盖范围比广域网大」，判断题。局域网范围小，广域网范围大，说法错误。\n【协议/层次】网络分类·覆盖范围。LAN局域网范围最小（几公里），WAN广域网范围最大（跨城市/国家）。\n【步骤/计算过程】\n① 局域网覆盖范围<广域网覆盖范围。\n② 题干说「局域网比广域网大」→错误。\n③ 选项：A「正确」❌；B「错误」✅。\n【答案】B 错误\n【易错】①读反大小关系：局域网小、广域网大；②LAN<MAN<WAN按范围递增；③口诀：「局域网小，广域网大」。","steps":["【考点】网络分类","【协议/层次】网络分类·覆盖范围。LAN局域网范围最小（几公里），WAN广域网范围最大（跨城市/国家）。","【步骤/计算过程】\n① 局域网覆盖范围<广域网覆盖范围。\n② 题干说「局域网比广域网大」→错误。\n③ 选项：A「正确」❌；B「错误」✅。","【答案】错误","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
