  window.STUDY_DATA.questions.push({"id":"nn1403","module":"major","subject":"计算机网络基础","chapter":"ch-net-1","knowledgePoint":"OSI参考模型","type":"judge","typeLabel":"判断","stem":"OSI参考模型是实际使用的标准。","options":["正确","错误"],"answer":"错误","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["网络概述","OSI"],"analysis":"【审题】题干说「OSI参考模型是实际使用的标准」，判断题。OSI是理论参考模型，不是实际标准，说法错误。\n【协议/层次】OSI vs TCP/IP。OSI/RM是理论参考模型（ISO提出），指导分层设计；实际Internet使用TCP/IP协议族（事实标准）。\n【步骤/计算过程】\n① OSI=理论参考模型，不是实际使用标准。\n② 实际标准=TCP/IP。\n③ 选项：A「正确」❌；B「错误」✅。\n【答案】B 错误\n【易错】①以为OSI是实际标准：OSI完整但复杂，实际网络用TCP/IP；②「OSI参考模型」名字里的「参考」就说明是参考不是实施标准；③口诀：「OSI理论参考，TCP/IP实际标准」。","steps":["【用寄快递类比】","应用层 = 你写的信内容（HTTP、FTP等）","传输层 = 快递小哥（TCP可靠送、UDP扔门口）","网络层 = 分拣中心导航（IP地址找路）","网络接口层 = 高速公路（物理运输）","【本题问的协议在哪层，对号入座】","【答案】错误","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["IP是网络层，TCP是传输层，HTTP是应用层，别搞混"]});
