  window.STUDY_DATA.questions.push({"id":"nx04","module":"major","subject":"计算机网络基础","chapter":"ch-net-1","knowledgePoint":"网络体系结构","type":"judge","typeLabel":"判断","difficulty":1,"difficultyLabel":"基础","stem":"IP 协议提供可靠传输。","options":["正确","错误"],"answer":"错误","tags":["IP"],"source":"batch","pitfalls":["IP是网络层，TCP是传输层，HTTP是应用层，别搞混"],"explainLevel":"subject-specific","hint":"【结论】错误 【考点】网络体系结构 【一步步怎么算】 ① 题目：IP 协议提供可靠传输。。 ② 调用「网络体系结构」规则（掩码/端口/层次）。 ③ 按步骤计算或对照表格。 ④ 得到 错误。 【其他选项为何不对】 • A「正确」：层次/端口/","analysis":"【审题】题干说「IP协议提供可靠传输」，判断题。IP是不可靠传输，说法错误。\n【协议/层次】网络层·IP。IP提供无连接、不可靠的「尽力而为」传输，不保证到达、不保证顺序、不保证不重复。可靠传输由TCP保证。\n【步骤/计算过程】\n① IP不可靠→题干说「提供可靠传输」→错误。\n② 选项：A「正确」❌；B「错误」✅。\n【答案】B 错误\n【易错】①以为IP可靠：IP尽力而为，丢包不管；可靠是TCP的责任；②「IP不可靠，TCP可靠」；③口诀：「IP尽力而为」。","steps":["【用寄快递类比】","应用层 = 你写的信内容（HTTP、FTP等）","传输层 = 快递小哥（TCP可靠送、UDP扔门口）","网络层 = 分拣中心导航（IP地址找路）","网络接口层 = 高速公路（物理运输）","【本题问的协议在哪层，对号入座】","【答案】错误","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"]});
  window.STUDY_DATA.questions.push({"id":"nn2304","module":"major","subject":"计算机网络基础","chapter":"ch-net-2","knowledgePoint":"奈奎斯特","type":"judge","typeLabel":"判断","stem":"香农定理描述了有噪声信道的最大传输速率。","options":["正确","错误"],"answer":"正确","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["物理层","香农"],"analysis":"【审题】题干说「香农定理描述了有噪声信道的最大传输速率」，判断题。说法正确。\n【协议/层次】物理层·信道容量。香农定理（Shannon）：C=B·log2(1+S/N)，描述有噪声信道的极限数据率（最大传输速率）。奈奎斯特定理：C=2B·log2(V)，描述无噪声信道。\n【步骤/计算过程】\n① 香农定理=有噪声信道最大速率→正确。\n② 选项：A「正确」✅；B「错误」❌。\n【答案】A 正确\n【易错】①与奈奎斯特混：香农有噪声，奈奎斯特无噪声；②题干说「有噪声」对应香农→正确。","steps":["【考点】奈奎斯特","【协议/层次】物理层·信道容量。香农定理（Shannon）：C=B·log2(1+S/N)，描述有噪声信道的极限数据率（最大传输速率）。奈奎斯特定理：C=2B·log2(V)，描述无噪声信道。","【步骤/计算过程】\n① 香农定理=有噪声信道最大速率→正确。\n② 选项：A「正确」✅；B「错误」❌。","【答案】正确","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
