  window.STUDY_DATA.questions.push({"id":"nn2502","module":"major","subject":"计算机网络基础","chapter":"ch-net-2","knowledgePoint":"信道容量","type":"judge","typeLabel":"判断","stem":"信道带宽越大，最高数据率越高。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["物理层","带宽"],"analysis":"【审题】题干说「信道带宽越大，最高数据率越高」，判断题。带宽大→数据率高，说法正确。\n【协议/层次】物理层·信道容量。奈奎斯特/香农公式都表明：带宽B越大，信道容量C越大（最高数据率越高）。\n【步骤/计算过程】\n① 带宽B↑→容量C↑→正确。\n② 选项：A「正确」✅；B「错误」❌。\n【答案】A 正确\n【易错】①方向搞反：带宽大→数据率高；②香农C=B·log2(1+S/N)，B越大C越大；③说法正确。","steps":["【考点】信道容量","【协议/层次】物理层·信道容量。奈奎斯特/香农公式都表明：带宽B越大，信道容量C越大（最高数据率越高）。","【步骤/计算过程】\n① 带宽B↑→容量C↑→正确。\n② 选项：A「正确」✅；B「错误」❌。","【答案】正确","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
