  window.STUDY_DATA.questions.push({"id":"nn2607","module":"major","subject":"计算机网络基础","chapter":"ch-net-2","knowledgePoint":"信道带宽","type":"judge","typeLabel":"判断","stem":"信道带宽单位是Hz。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["物理层","带宽"],"analysis":"【审题】题干说「信道带宽单位是Hz」，判断题。信道带宽（频率范围）单位=Hz，说法正确。\n【协议/层次】物理层·带宽。信道带宽两种含义：①频带宽度（Hz）：信道频率范围；②数据率（bps）：最高数据率。题干说「信道带宽单位是Hz」指频率带宽，正确。\n【步骤/计算过程】\n① 信道带宽（频率）单位=Hz→正确。\n② 选项：A「正确」✅；B「错误」❌。\n【答案】A 正确\n【易错】①与数据率bps混：bps是数据率单位，Hz是频率带宽单位；②「信道带宽」既可指Hz也可指bps，题干说Hz是频率含义，正确。","steps":["【考点】信道带宽","【协议/层次】物理层·带宽。信道带宽两种含义：①频带宽度（Hz）：信道频率范围；②数据率（bps）：最高数据率。题干说「信道带宽单位是Hz」指频率带宽，正确。","【步骤/计算过程】\n① 信道带宽（频率）单位=Hz→正确。\n② 选项：A「正确」✅；B「错误」❌。","【答案】正确","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn2609","module":"major","subject":"计算机网络基础","chapter":"ch-net-2","knowledgePoint":"奈奎斯特","type":"judge","typeLabel":"判断","stem":"奈奎斯特定理是无噪声信道的极限。","options":["正确","错误"],"answer":"正确","difficulty":1,"difficultyLabel":"基础","source":"new2026","tags":["物理层","奈奎斯特"],"analysis":"【审题】题干说「奈奎斯特定理是无噪声信道的极限」，判断题。奈奎斯特=无噪声，说法正确。\n【协议/层次】物理层·信道容量。奈奎斯特定理：C=2B·log2(V)，描述无噪声信道的极限数据率。香农定理：C=B·log2(1+S/N)，描述有噪声信道。\n【步骤/计算过程】\n① 奈奎斯特=无噪声→正确。\n② 选项：A「正确」✅；B「错误」❌。\n【答案】A 正确\n【易错】①与香农混：奈奎斯特无噪声，香农有噪声；②说法正确。","steps":["【考点】奈奎斯特","【协议/层次】物理层·信道容量。奈奎斯特定理：C=2B·log2(V)，描述无噪声信道的极限数据率。香农定理：C=B·log2(1+S/N)，描述有噪声信道。","【步骤/计算过程】\n① 奈奎斯特=无噪声→正确。\n② 选项：A「正确」✅；B「错误」❌。","【答案】正确","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
  window.STUDY_DATA.questions.push({"id":"nn3104","module":"major","subject":"计算机网络基础","chapter":"ch-net-3","knowledgePoint":"CRC校验","type":"judge","typeLabel":"判断","stem":"CRC校验可以检测出所有的传输错误。","options":["正确","错误"],"answer":"错误","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["数据链路层","CRC"],"analysis":"【审题】题干说「CRC校验可以检测出所有的传输错误」，判断题。CRC不能检测所有错误，说法错误。\n【协议/层次】数据链路层·CRC校验。CRC检错能力强，但不能100%检测所有错误（理论上存在漏检的错误模式，尽管概率极低）。\n【步骤/计算过程】\n① CRC不能检测所有错误→题干说「所有」→错误。\n② 选项：A「正确」❌；B「错误」✅。\n【答案】B 错误\n【易错】①以为CRC万能：CRC检错能力强但非100%；②绝对化表述「所有」通常有问题；③说法错误。","steps":["【考点】CRC校验","【协议/层次】数据链路层·CRC校验。CRC检错能力强，但不能100%检测所有错误（理论上存在漏检的错误模式，尽管概率极低）。","【步骤/计算过程】\n① CRC不能检测所有错误→题干说「所有」→错误。\n② 选项：A「正确」❌；B「错误」✅。","【答案】错误","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
