  window.STUDY_DATA.questions.push({"id":"nn6603","module":"major","subject":"计算机网络基础","chapter":"ch-net-6","knowledgePoint":"WWW","type":"judge","typeLabel":"判断","stem":"万维网就是互联网。","options":["正确","错误"],"answer":"错误","difficulty":2,"difficultyLabel":"强化","source":"new2026","tags":["应用层","WWW"],"analysis":"【审题】题干说「万维网就是互联网」，判断题。WWW≠Internet，说法错误。\n【协议/层次】网络概念。互联网（Internet）=网络的网络（TCP/IP互联的全球网络）；万维网（WWW）=Internet上的超文本应用（HTTP网页系统）。WWW是Internet上的应用，不是Internet本身。\n【步骤/计算过程】\n① WWW是Internet上的应用，不是Internet→错误。\n② 选项：A「正确」❌；B「错误」✅。\n【答案】B 错误\n【易错】①以为WWW=Internet：Internet是网络基础设施，WWW是其上的网页应用（还有Email、FTP等应用）；②「Internet≠WWW」；③说法错误。","steps":["【考点】WWW","【协议/层次】网络概念。互联网（Internet）=网络的网络（TCP/IP互联的全球网络）；万维网（WWW）=Internet上的超文本应用（HTTP网页系统）。WWW是Internet上的应用，不是Internet本身。","【步骤/计算过程】\n① WWW是Internet上的应用，不是Internet→错误。\n② 选项：A「正确」❌；B「错误」✅。","【答案】错误","【举一反三】做完这题后，遮住答案自己再算一遍，看能不能独立做出来"],"pitfalls":["分层思想是网络的核心"]});
